/** Download registry for the approved Refined Classic identity.
 * Outlined artwork is generated by pnpm brand:logos from scripts/brand/artwork.mjs.
 * Standalone white exports work in images, print tools and cover templates.
 */
export interface BrandLogo {
  id: string;
  name: string;
  description: string;
  src: string;
  whiteSrc: string;
  width: number;
  height: number;
  ratio: string;
  minHeight: number;
}

